body.script:
window.addEventListener("load", function () {
    const preloader = document.querySelector(".custom-preloader");

    // Wait for 5 seconds before fading out the preloader
    setTimeout(function () {
        preloader.style.opacity = "0";  // Start fading out after 5 seconds
        setTimeout(function () {
            preloader.style.display = "none";  // Hide preloader completely after fade-out
        }, 500);  // 500ms delay for smooth fade-out transition
    }, 1500);  // Preloader stays for 1.5 seconds (adjust to match your timing)
});

