// Initialize the Google Translate Widget
function googleTranslateElementInit() {
    new google.translate.TranslateElement({
        pageLanguage: 'en',
        includedLanguages: 'en,si,ta', // Add desired languages (English, Sinhala, Tamil)
        layout: google.translate.TranslateElement.InlineLayout.SIMPLE,
    }, 'google_translate_element');
}

// Language Selection Function
function setLanguage(lang) {
    document.cookie = `googtrans=/en/${lang}; path=/;`;
    localStorage.setItem('preferredLang', lang);
    window.location.reload();
}

// Apply Saved Language on Page Load
(function applySavedLanguage() {
    const savedLang = localStorage.getItem('preferredLang') || 'en';
    document.cookie = `googtrans=/en/${savedLang}; path=/;`;
    const languageSelector = document.getElementById('language-selector');
    if (languageSelector) {
        languageSelector.value = savedLang;
    }
})();

// Function to safely replace specific text in the page
function updateManualTranslations() {
    // Define manual translations for Sinhala
    const manualTranslations = {
        si: {

            "à¶´à·à¶»à·à¶¸à·à¶´à·à¶¯à¶±":"à¶´à·âà¶»à·à¶¸à·à¶´à·à¶¯à¶±",
            "à¶±à·à·à·":"à¶¸à·à¶½à· à¶´à·à¶§à·à·",
            "à·à·à¶¯à·à¶±à¶¸":"à¶´à·âà¶»à¶­à·à¶ à·à¶»",
            "à¶à¶«à·à¶©à·à¶ºà¶¸":"à·à¶à·à¶¯à¶º",
            "à¶à¶´à¶§ à¶à¶¶à¶§" : "à¶à¶´à·à¶±à· à¶à¶¶à¶§",
            "à¶©à·à¶¢à·à¶§à¶½à· à¶à¶°à·à¶à¶»à¶« à·à·à¶¯à·à¶º à·à·à¶¯à·à¶ºà·à·":"à¶©à·à¶¢à·à¶§à¶½à· à·à·à·à·à¶»à·à¶ à·à·à¶¸à¶»à·à·à¶±",
            "à·à·à¶­à·à¶à¶º":"CERT",
            "à¶´à·à¶»à·à·à·à¶º":"à¶´à·âà¶»à·à·à·à¶º",
            "à¶à¶»à·à¶¸à·à¶±à·à¶­":"à¶à·à·à·à¶­à·âà¶»",
            "à¶¸à·à¶½à·à¶º": "à¶¸à·à¶½à·âà¶º",
            "à¶»à·à¶¢à·à¶º":"à¶»à·à¶¢à·âà¶º",
            "à¶à¶­à·à¶´à·à¶½à· à¶½à·à¶´à·à¶±à¶º":"à·à·à¶¯à·âà¶ºà·à¶­à· à¶½à·à¶´à·à¶±à¶º",
            "à¶¸à¶°à·à¶ºà·à·à¶®à·à¶±à¶º":"à¶¸à¶°à·âà¶ºà·à·à¶®à·à¶±à¶º",
            "à¶»à·à·à·à¶ºà¶­à· à¶´à·à¶»à¶­à·à¶´à¶­à·à¶­à·à¶º":"à¶»à·à·à·âà¶ºà¶­à· à¶´à·âà¶»à¶­à·à¶´à¶­à·à¶­à·à¶º",
            "à¶´à¶­à·âà¶»à·à¶à·à· à¶¯à·à¶ºà¶ à·à¶±à·à¶±":"à¶´à¶­à·âà¶»à·à¶à·à·à¶§ à¶½à·à¶ºà·à¶´à¶¯à·à¶à¶ à· à·à¶±à·à¶±",
            "à¶¯à·à¶±à·à¶¸ à¶¯à·à¶ºà¶ à·à¶±à·à¶±":"à¶½à·à¶ºà·à¶´à¶¯à·à¶à¶ à· à·à¶±à·à¶±",
            "à¶¸à·à¶°à·à¶º":"à¶¸à·à¶°à·âà¶º",
            "à·à·à¶¸à·à¶±à·à¶º":"à·à·à¶¸à·à¶±à·âà¶º"
        }
    };

    // Detect the current language from the Google Translate cookie
    const match = document.cookie.match(/googtrans=\/en\/(si|ta|en)/i);
    const currentLanguage = match ? match[1] : "en";

    // Only apply manual translation for Sinhala
    if (currentLanguage === "si") {
        // Recursively replace the text in all text nodes
        walkAndReplaceText(document.body, manualTranslations.si);
    }
}

// Function to walk through the DOM and replace text safely in text nodes
function walkAndReplaceText(node, translations) {
    if (node.nodeType === Node.TEXT_NODE) {
        // Replace the text content if it matches the target text
        Object.keys(translations).forEach((key) => {
            if (node.textContent.includes(key)) {
                node.textContent = node.textContent.replace(key, translations[key]);
            }
        });
    } else if (node.nodeType === Node.ELEMENT_NODE) {
        // If the node is an element, recurse through its children
        node.childNodes.forEach(childNode => walkAndReplaceText(childNode, translations));
    }
}

// Observe DOM changes to reapply manual translations after Google Translate processes the page
const observer = new MutationObserver(() => {
    updateManualTranslations();
});

observer.observe(document.body, {
    childList: true,
    subtree: true
});

// Initial call to apply translations when the page is loaded
window.addEventListener("load", updateManualTranslations);

div.script:
;(function($){
    "use strict";
    $(document).ready(function () {
        // MAILCHIMP
        if ($(".mailchimp").length > 0) {
            $(".mailchimp").ajaxChimp({
                callback: mailchimpCallback,
                url: "https://envytheme.us20.list-manage.com/subscribe/post?u=60e1ffe2e8a68ce1204cd39a5&id=42d6d188d9"
            });
        }
        if ($(".mailchimp_two").length > 0) {
            $(".mailchimp_two").ajaxChimp({
                callback: mailchimpCallback,
                url: "https://envytheme.us20.list-manage.com/subscribe/post?u=60e1ffe2e8a68ce1204cd39a5&id=42d6d188d9" //Replace this with your own mailchimp post URL. Don't remove the "". Just paste the url inside "".
            });
        }
        $(".memail").on("focus", function () {
            $(".mchimp-errmessage").fadeOut();
            $(".mchimp-sucmessage").fadeOut();
        });
        $(".memail").on("keydown", function () {
            $(".mchimp-errmessage").fadeOut();
            $(".mchimp-sucmessage").fadeOut();
        });
        $(".memail").on("click", function () {
            $(".memail").val("");
        });

        function mailchimpCallback(resp) {
            if (resp.result === "success") {
                $(".mchimp-errmessage")l(resp.msg).fadeIn(1000);
                $(".mchimp-sucmessage").fadeOut(500);
            } else if (resp.result === "error") {
                $(".mchimp-errmessage")l(resp.msg).fadeIn(1000);
            }
        }
    });
})(jQuery)

link.script:
const lazyloadRunObserver = () => {
	const lazyloadBackgrounds = document.querySelectorAll( `.e-con.e-parent:not(.e-lazyloaded)` );
	const lazyloadBackgroundObserver = new IntersectionObserver( ( entries ) => {
		entries.forEach( ( entry ) => {
			if ( entry.isIntersecting ) {
				let lazyloadBackground = entry.target;
				if( lazyloadBackground ) {
					lazyloadBackground.classList.add( 'e-lazyloaded' );
				}
				lazyloadBackgroundObserver.unobserve( entry.target );
			}
		});
	}, { rootMargin: '200px 0px 200px 0px' } );
	lazyloadBackgrounds.forEach( ( lazyloadBackground ) => {
		lazyloadBackgroundObserver.observe( lazyloadBackground );
	} );
};
const events = [
	'DOMContentLoaded',
	'elementor/lazyload/observe',
];
events.forEach( ( event ) => {
	document.addEventListener( event, lazyloadRunObserver );
} );

(function () {
	var c = document.body.className;
	c = c.replace(/woocommerce-no-js/, 'woocommerce-js');
	document.body.className = c;
})();
